UPDATE dpa_base.t_dpa_base_page_design
SET
delete_flag = false,
required = #{pageDesignModel.required},
enable_belong_field = #{pageDesignModel.enableBelongField}

    , page_name_en = #{pageDesignModel.pageNameEn}


    , page_name_chn = #{pageDesignModel.pageNameChn}


    , page_detail = #{pageDesignModel.pageDetail}


    , icon = #{pageDesignModel.icon}


    , association_table_codes = #{pageDesignModel.associationTableCodes}


    , coupling_table_codes = #{pageDesignModel.couplingTableCodes}


    , coupling_field_codes = #{pageDesignModel.couplingFieldCodes}


    , coupling_process_codes = #{pageDesignModel.couplingProcessCodes}


    , coupling_home_page_process_codes = #{pageDesignModel.couplingHomePageProcessCodes}


    , bubble_process_detail = #{pageDesignModel.bubbleProcessDetail}


    , remark = #{pageDesignModel.remark}


    , qr_code_belong_process = #{pageDesignModel.qrCodeBelongProcess,jdbcType=ARRAY,typeHandler=com.futurecraftsmen.pms.service.domain.ArrayTypeHandler}

WHERE page_code = #{pageDesignModel.pageCode} AND delete_flag = false
